changeSet.sql:
UPDATE notification_template SET subject = 'Password reset - Manage your online reporting service', text = 'You have successfully reset your password for the online reporting service. You can now [sign in to your account](${homeUrl}).
If you did not request this reset you must [contact your regulator](${contactRegulator}).
This is an automatic email - please do not reply to this address.' WHERE name = 'ResetPasswordConfirmation';

rollback.sql:
UPDATE notification_template SET subject = 'Password reset - Manage your UK ETS reporting', text = 'You have successfully reset your password for the UK ETS reporting service. You can now [sign in to your account](${homeUrl}).
If you did not request this reset you must [contact your regulator](${contactRegulator}).
This is an automatic email - please do not reply to this address.' WHERE name = 'ResetPasswordConfirmation';

