changeSet.sql:
INSERT INTO notification_template ( id, name, subject, competent_authority, event_trigger, account_type, workflow, role_type, is_managed, last_updated_date, text ) VALUES ( nextval('notification_template_seq'), 'Registry integration email template consume registry error', 'ACTION REQUIRED - Error with integration point `Update emissions value` for Operator: ${operatorName} with Emitter ID: ${emitterId} ', 'OPRED', null, 'AVIATION', null, null, false, CURRENT_TIMESTAMP, 'Dear Regulator,
The integration point "Update emissions value" has failed with error: "${errorCode} - ${errorMessage}" for Operator: ${operatorName} with Emitter ID: ${emitterId}
Please review the affected fields: UK ETS Registry ID: {registryId}
If there is a need, then please raise a support ticket including the following information:
Source system identifier: ${sourceSystem} Message ID (correlation ID): ${correlationId} Payload: Operator ID: ${registryId}, Year: ${year}, Emissions: ${emissions} Error code: ${errorCode} Error message: ${errorMessage}
Thank you.') ;

rollback.sql:
delete from notification_template
where name = 'Registry integration email template consume registry error'
and competent_authority = 'OPRED' and account_type = 'AVIATION';

