changeSet.sql:
WITH constants (name, subject, text_content) AS ( VALUES ( 'Registry integration set operator id error fordway', 'ACTION REQUIRED - Error with integration point ''Registry/Operator ID''', $$Dear Fordway,
The integration point 'Registry/Operator ID' has failed with error(s):
<#list errors as code,description> - **${code?replace("ERROR_", "")}** - **${description}** </#list>
for Operator: ${operatorName!""} with Emitter ID: ${emitterId!""}
Actions: Please contact the development team for root cause investigation
Source system identifier: ${sourceSystem}
Message ID (correlation ID): ${correlationId}
Payload: Operator ID: ${registryId!""}, Emitter Id: ${emitterId!""}, Competent Authority: ${competentAuthorityName!""}
Thank you.$$ ) ), templates_to_create (ca_name, account_type) AS ( VALUES ('ENGLAND', 'AVIATION'), ('SCOTLAND', 'AVIATION'), ('WALES', 'AVIATION'), ('NORTHERN_IRELAND', 'AVIATION'), ('OPRED', 'AVIATION'), ('ENGLAND', 'INSTALLATION'), ('SCOTLAND', 'INSTALLATION'), ('WALES', 'INSTALLATION'), ('NORTHERN_IRELAND', 'INSTALLATION'), ('OPRED', 'INSTALLATION') ) INSERT INTO notification_template ( id, name, subject, competent_authority, event_trigger, account_type, workflow, role_type, is_managed, last_updated_date, text ) SELECT nextval('notification_template_seq'), c.name, c.subject, t.ca_name, null, t.account_type, null, null, false, CURRENT_TIMESTAMP, c.text_content FROM constants c CROSS JOIN templates_to_create t;

WITH constants (name, subject, text_content) AS ( VALUES ( 'Registry integration set operator id error regulator', 'ACTION REQUIRED - Error with integration point ''Registry/Operator ID'' for Operator: ${operatorName!""} with Emitter ID: ${emitterId!""}', $$Dear Regulator,
The integration point 'Registry/Operator ID' has failed with error(s):
<#list errors as code,description> - **${code?replace("ERROR_", "")}** - **${description}** </#list>
for Operator: ${operatorName!""} with Emitter ID: ${emitterId!""} and Registry/Operator ID: ${registryId!""}
Please review the affected fields: Emitter ID and Registry/Operator ID
If there is a need, then please raise a support ticket including the following information:
Source system identifier: ${sourceSystem}
Message ID (correlation ID): ${correlationId}
Payload: Operator ID: ${registryId!""}, Emitter Id: ${emitterId!""}, Competent Authority: ${competentAuthorityName!""}
Thank you.$$ ) ), templates_to_create (ca_name, account_type) AS ( VALUES ('ENGLAND', 'AVIATION'), ('SCOTLAND', 'AVIATION'), ('WALES', 'AVIATION'), ('NORTHERN_IRELAND', 'AVIATION'), ('OPRED', 'AVIATION'), ('ENGLAND', 'INSTALLATION'), ('SCOTLAND', 'INSTALLATION'), ('WALES', 'INSTALLATION'), ('NORTHERN_IRELAND', 'INSTALLATION'), ('OPRED', 'INSTALLATION') ) INSERT INTO notification_template ( id, name, subject, competent_authority, event_trigger, account_type, workflow, role_type, is_managed, last_updated_date, text ) SELECT nextval('notification_template_seq'), c.name, c.subject, t.ca_name, null, t.account_type, null, null, false, CURRENT_TIMESTAMP, c.text_content FROM constants c CROSS JOIN templates_to_create t;

