Payload: Operator ID: ${registryId!""}, Emitter Id: ${emitterId!""}, Competent Authority: ${competentAuthorityName!""}

Thank you.$$,
                last_updated_date = CURRENT_TIMESTAMP
            WHERE name = 'Registry integration set operator id error information regulator';

